/**
 * 官方五源合一（优酷 / 腾讯 / 奇艺 / 芒果 / 360影视）
 * OK影视 / TVBox 原生 JS0 爬虫源 —— 不依赖 drpy2.min.js
 *
 * 三条铁律：
 * A. 所有函数同步 return JSON 字符串，禁止 async/await（QuickJS 不驱动 Promise）
 * B. 图片地址过 buildPic()，http 开头原样返回
 * C. 播放地址用网页直链，play() 返回 {parse:1, jx:1}
 */

let host = 'https://www.iqiyi.com';
let UA = 'Mozilla/5.0 (Linux; Android 11; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/107.0.0.0 Mobile Safari/537.36';
let PC_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
let MOBILE_UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

// ==================== 工具函数 ====================
function buildPic(url) {
    if (!url) return '';
    url = String(url);
    if (url.indexOf('http') === 0) return url;
    return url;
}

function getJson(url, headers) {
    let res = req(url, { headers: headers || { 'User-Agent': PC_UA } });
    return JSON.parse(res.content);
}

function getText(url, headers) {
    let res = req(url, { headers: headers || { 'User-Agent': PC_UA } });
    return res.content;
}

function urljoin(base, path) {
    if (!path) return '';
    if (path.indexOf('http') === 0) return path;
    if (path.indexOf('//') === 0) return 'https:' + path;
    if (path.indexOf('/') === 0) {
        let m = base.match(/^(https?:\/\/[^\/]+)/);
        return (m ? m[1] : '') + path;
    }
    return base + '/' + path;
}

function urlDeal(url) {
    if (!url) return '';
    url = String(url);
    if (url.indexOf('//') === 0) return 'https:' + url;
    if (url.indexOf('http') === 0) return url;
    if (url.indexOf('/') === 0) return 'https://www.360kan.com' + url;
    return url;
}

// 简易 HTML 块提取：.list_item
function pdfa(html, sel) {
    let res = [];
    if (sel === '.list_item') {
        let re = /<div class="list_item"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/g;
        let m;
        while ((m = re.exec(html)) !== null) res.push(m[1]);
    }
    return res;
}

// 简易元素取值：img&&alt / img&&src / a&&Text / a&&data-float
function _firstAttr(html, tag, attr) {
    let re = new RegExp('<' + tag + '[^>]*\\s' + attr + '="([^"]*)"', 'i');
    let m = html.match(re);
    return m ? m[1] : '';
}

function _firstText(html, tag) {
    let re = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
    let m = html.match(re);
    if (!m) return '';
    return m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function pdfh(html, rule) {
    if (!rule) return '';
    let parts = rule.split('&&');
    let tag = parts[0] || '';
    let attr = parts[1] || '';
    if (/^img$/i.test(tag) && attr === 'alt') return _firstAttr(html, 'img', 'alt');
    if (/^img$/i.test(tag) && attr === 'src') return _firstAttr(html, 'img', 'src');
    if (/^a$/i.test(tag) && attr === 'Text') return _firstText(html, 'a');
    if (/^a$/i.test(tag) && attr) return _firstAttr(html, 'a', attr);
    return '';
}

function pd(html, rule) { return pdfh(html, rule); }

// 简易 JSON 选择器（支持 .a.b 与 pjfa 数组）
function pjfh(obj, path) {
    let parts = String(path).replace(/^\./, '').split('.');
    let cur = obj;
    for (let i = 0; i < parts.length; i++) {
        if (cur == null) return '';
        cur = cur[parts[i]];
    }
    return cur;
}

function pjfa(obj, path) {
    let parts = String(path).replace(/^\./, '').split('.');
    let cur = obj;
    for (let i = 0; i < parts.length; i++) {
        if (cur == null) return [];
        cur = cur[parts[i]];
    }
    return Array.isArray(cur) ? cur : [];
}

