function mgtv_detail(id) {
    let VOD = { vod_id: id, vod_name: '', vod_pic: '', vod_remarks: '', vod_content: '', vod_play_from: 'mgtv', vod_play_url: '' };
    let input = 'https://pcweb.api.mgtv.com/episode/list?page=1&size=50&video_id=' + id;
    let json = null;
    try { json = JSON.parse(getText(input, { 'User-Agent': PC_UA, 'Referer': 'https://www.mgtv.com' })); } catch (e) {}
    if (!json || !json.data) return JSON.stringify({ list: [VOD] });
    let d = json.data;
    let host = 'https://www.mgtv.com';
    let ourl = (d.list && d.list.length > 0) ? d.list[0].url : (d.series && d.series[0] ? d.series[0].url : '');
    if (!/^http/.test(ourl)) ourl = host + ourl;
    let html = '';
    try { html = getText(ourl, { 'User-Agent': MOBILE_UA, 'Referer': 'https://www.mgtv.com' }); } catch (e) {}
    if (html.indexOf('window.location =') >= 0) {
        let m = html.match(/content="[^"]*url=([^"]*)"/);
        if (m) {
            ourl = m[1];
            try { html = getText(ourl, { 'User-Agent': MOBILE_UA, 'Referer': 'https://www.mgtv.com' }); } catch (e) {}
        }
    }
    try {
        let m = html.match(/window\.__INITIAL_STATE__\s*=\s*([\s\S]*?)<\/script>/);
        if (m) {
            let js = JSON.parse(m[1].replace(/;\s*$/, ''));
            let vi = js.playPage && js.playPage.videoinfo;
            if (vi) {
                VOD.vod_name = vi.clipName;
                VOD.vod_area = vi['1'] || '';
                VOD.vod_actor = vi['4'] || '';
                VOD.vod_remarks = vi['3'] || '';
                VOD.vod_pic = buildPic(vi.colImage);
                VOD.vod_content = vi['5'] || '';
                if (!VOD.vod_name) VOD.vod_name = vi['0'];
            }
        }
    } catch (e) {}

    function getRjpg(imgUrl, xs) {
        xs = xs || 3;
        if (!imgUrl) return imgUrl;
        let picSize = /jpg_/.test(imgUrl) ? imgUrl.split('jpg_')[1].split('.')[0] : false;
        let rjpg = false;
        if (picSize) {
            let a = parseInt(picSize.split('x')[0]) * xs;
            let b = parseInt(picSize.split('x')[1]) * xs;
            rjpg = a + 'x' + b + '.jpg';
        }
        return (/jpg_/.test(imgUrl) && rjpg) ? imgUrl.replace(imgUrl.split('jpg_')[1], rjpg) : imgUrl;
    }

    let urls = [];
    if (d.total === 1 && d.list && d.list.length === 1) {
        let data = d.list[0];
        urls.push(data.t4 + '$https://www.mgtv.com' + data.url);
    } else if (d.list && d.list.length > 1) {
        let total_page = d.total_page || 1;
        for (let i = 1; i <= total_page; i++) {
            if (i > 1) {
                try {
                    json = JSON.parse(getText(input.replace('page=1', 'page=' + i), { 'User-Agent': PC_UA, 'Referer': 'https://www.mgtv.com' }));
                    d = json.data;
                } catch (e) { continue; }
            }
            (d.list || []).forEach(function (data) {
                if (data.isIntact === '1') {
                    urls.push(data.t4 + '$https://www.mgtv.com' + data.url);
                }
            });
        }
    }
    VOD.vod_play_url = urls.join('#');
    return JSON.stringify({ list: [VOD] });
}

function mgtv_search(wd, pg) {
    let url = 'https://mobileso.bz.mgtv.com/msite/search/v2?q=' + encodeURIComponent(wd) + '&pn=' + (pg || 1) + '&pc=10';
    let json = null;
    let list = [];
    try { json = JSON.parse(getText(url, { 'User-Agent': PC_UA, 'Referer': 'https://www.mgtv.com' })); } catch (e) {}
    if (json && json.data && json.data.contents) {
        json.data.contents.forEach(function (data) {
            if (data.type === 'media' && data.data && data.data[0]) {
                let item = data.data[0];
                if (item.source === 'imgo' && item.url) {
                    let m = item.url.match(/.*\/(.*?)\.html/);
                    if (!m) return;
                    list.push({
                        vod_id: 'mgtv$' + m[1],
                        vod_name: String(item.title).replace(/<B>|<\/B>/g, ''),
                        vod_pic: buildPic(item.img),
                        vod_remarks: (item.desc || []).join(',')
                    });
                }
            }
        });
    }
    return list;
}

