function q360_detail(id) {
    let parts = id.split('$');
    let cat = parts[0];
    let ent = parts[1];
    let VOD = { vod_id: id, vod_name: '', vod_pic: '', vod_remarks: '', vod_content: '', vod_play_from: '', vod_play_url: '' };
    let input = 'https://api.web.360kan.com/v1/detail?cat=' + cat + '&id=' + ent;
    let html = null;
    try { html = JSON.parse(getText(input, { 'User-Agent': MOBILE_UA, 'Referer': 'https://www.360kan.com/' })); } catch (e) {}
    if (!html || !html.data) return JSON.stringify({ list: [VOD] });
    let data = html.data;
    VOD.vod_name = data.title || '';
    VOD.vod_pic = buildPic(data.cdncover);
    VOD.vod_remarks = (data.area || []).join(',');
    VOD.vod_content = data.description || '';
    let delta = 50;
    let vod_play = {};
    let sites = data.playlink_sites || [];
    for (let si = 0; si < sites.length; si++) {
        let site = sites[si];
        let vodItems = [];
        if (data.allupinfo && data.allupinfo[site]) {
            let total = parseInt(data.allupinfo[site]) || 0;
            for (let j = 1; j < total; j += delta) {
                let end = Math.min(total, j + delta - 1);
                let url2 = input + '&start=' + j + '&end=' + end + '&site=' + site;
                let vd = null;
                try { vd = JSON.parse(getText(url2, { 'User-Agent': MOBILE_UA, 'Referer': 'https://www.360kan.com/' })).data; } catch (e) {}
                if (!vd) continue;
                if (vd.allepidetail && vd.allepidetail[site]) {
                    vd.allepidetail[site].forEach(function (item) {
                        vodItems.push((item.playlink_num || '') + '$' + urlDeal(item.url || ''));
                    });
                } else if (vd.defaultepisode) {
                    vd.defaultepisode.forEach(function (item) {
                        vodItems.push(((item.period || '') + (item.name || '')) + '$' + urlDeal(item.url || ''));
                    });
                }
            }
        } else if (data.playlinksdetail && data.playlinksdetail[site]) {
            let item = data.playlinksdetail[site];
            vodItems.push((item.sort || '') + '$' + urlDeal(item.default_url || ''));
        }
        if (vodItems.length > 0) vod_play[site] = vodItems.join('#');
    }
    let tabs = Object.keys(vod_play);
    if (tabs.length > 0) {
        let playUrls = [];
        for (let i = 0; i < tabs.length; i++) playUrls.push(vod_play[tabs[i]]);
        VOD.vod_play_from = tabs.join('$$$');
        VOD.vod_play_url = playUrls.join('$$$');
    }
    return JSON.stringify({ list: [VOD] });
}

function q360_search(wd, pg) {
    let url = 'https://api.so.360kan.com/index?force_v=1&kw=' + encodeURIComponent(wd) + '&from=&pageno=' + (pg || 1) + '&v_ap=1&tab=all';
    let json = null;
    let list = [];
    try { json = JSON.parse(getText(url, { 'User-Agent': MOBILE_UA, 'Referer': 'https://www.360kan.com/' })); } catch (e) {}
    if (json && json.data && json.data.longData && json.data.longData.rows) {
        json.data.longData.rows.forEach(function (row) {
            if (!row.cat_id || !row.en_id) return;
            list.push({
                vod_id: '360$' + row.cat_id + '$' + row.en_id,
                vod_name: row.titleTxt || row.titlealias,
                vod_pic: buildPic(row.cover),
                vod_remarks: row.cat_name || ''
            });
        });
    }
    return list;
}

