function category(tid, pg, filter, extend) {
    pg = pg || 1;
    extend = extend || {};
    if (tid.indexOf('youku:') === 0) return youku_category(tid.split(':')[1], pg, extend);
    if (tid.indexOf('qq:') === 0) return qq_category(tid.split(':')[1], pg, extend);
    if (tid.indexOf('iqiyi:') === 0) return iqiyi_category(tid.split(':')[1], pg, extend);
    if (tid.indexOf('mgtv:') === 0) return mgtv_category(tid.split(':')[1], pg, extend);
    if (tid.indexOf('360:') === 0) return q360_category(tid.split(':')[1], pg, extend);
    return JSON.stringify({ page: pg, pagecount: 0, limit: 0, total: 0, list: [] });
}

function detail(id) {
    if (id.indexOf('youku$') === 0) return youku_detail(id.split('$')[1]);
    if (id.indexOf('qq$') === 0) return qq_detail(id.split('$')[1]);
    if (id.indexOf('iqiyi$') === 0) return iqiyi_detail(id.split('$')[1]);
    if (id.indexOf('mgtv$') === 0) return mgtv_detail(id.split('$')[1]);
    if (id.indexOf('360$') === 0) return q360_detail(id.substring(4));
    return JSON.stringify({ list: [] });
}

function search(wd, quick) {
    wd = wd || '';
    let list = [];
    let yk = youku_search(wd, 1);
    let qq = qq_search(wd, 1);
    let iq = iqiyi_search(wd, 1);
    let mg = mgtv_search(wd, 1);
    let q3 = q360_search(wd, 1);
    list = list.concat(yk, qq, iq, mg, q3);
    return JSON.stringify({ list: list });
}

function play(flag, id, flags) {
    return JSON.stringify({ parse: 1, jx: 1, url: id });
}

